mapper.delete:
DELETE
FROM skill_disabled_rule
WHERE scope_key = #{scopeKey} AND skill_name = #{skillName}

mapper.update:
UPDATE OR IGNORE skill_disabled_rule
SET skill_name = #{to}
WHERE skill_name = #{from} AND scope_key = #{scopeKey}

mapper.delete:
DELETE
FROM skill_disabled_rule
WHERE skill_name = #{from} AND scope_key = #{scopeKey}

mapper.insert:
INSERT OR IGNORE INTO skill_disabled_rule (scope_key, skill_name) SELECT #{toScopeKey}, skill_name
FROM skill_disabled_rule
WHERE scope_key = #{fromScopeKey}
